// Browser wiring for core/host-api.compat.ts: assigns the compat facade, reads old globals late.
// The factory is generated by l0/emit.mjs; this file only supplies the window side.
(function () {
  "use strict";
  window.hostApi = createCompatHostApi({
    readGlobal: function (name) {
      try {
        return window[name];
      } catch (e) {
        return undefined;
      }
    },
  });
})();
